CREATE TABLE IF NOT EXISTS `holdings` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `symbol` TEXT NOT NULL, `name` TEXT NOT NULL, `assetType` TEXT NOT NULL, `quantity` REAL NOT NULL, `buyPrice` REAL NOT NULL, `buyDate` INTEGER NOT NULL, `sector` TEXT NOT NULL, `notes` TEXT NOT NULL)
CREATE TABLE IF NOT EXISTS `paper_account` (`id` INTEGER NOT NULL, `cashBalance` REAL NOT NULL, `initialBalance` REAL NOT NULL, `realizedPnl` REAL NOT NULL, `totalTrades` INTEGER NOT NULL, `winningTrades` INTEGER NOT NULL, PRIMARY KEY(`id`))
CREATE TABLE IF NOT EXISTS `paper_positions` (`symbol` TEXT NOT NULL, `name` TEXT NOT NULL, `quantity` INTEGER NOT NULL, `averageBuyPrice` REAL NOT NULL, `currentPrice` REAL NOT NULL, `stopLoss` REAL, `targetPrice` REAL, `openedAt` INTEGER NOT NULL, PRIMARY KEY(`symbol`))
CREATE TABLE IF NOT EXISTS `paper_orders` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `symbol` TEXT NOT NULL, `side` TEXT NOT NULL, `quantity` INTEGER NOT NULL, `price` REAL NOT NULL, `orderType` TEXT NOT NULL, `status` TEXT NOT NULL, `realizedPnl` REAL NOT NULL, `timestamp` INTEGER NOT NULL, `notes` TEXT NOT NULL)
CREATE TABLE IF NOT EXISTS `pan_vault` (`panNumber` TEXT NOT NULL, `holderName` TEXT NOT NULL, `relation` TEXT NOT NULL, `addedAt` INTEGER NOT NULL, PRIMARY KEY(`panNumber`))
CREATE TABLE IF NOT EXISTS `allotment_records` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `maskedPan` TEXT NOT NULL, `ipoSymbol` TEXT NOT NULL, `ipoName` TEXT NOT NULL, `sharesApplied` INTEGER NOT NULL, `sharesAllotted` INTEGER NOT NULL, `status` TEXT NOT NULL, `registrar` TEXT NOT NULL, `checkedAt` INTEGER NOT NULL, `applicationNo` TEXT NOT NULL)
CREATE TABLE IF NOT EXISTS `watchlist` (`symbol` TEXT NOT NULL, `name` TEXT NOT NULL, `assetType` TEXT NOT NULL, `addedPrice` REAL NOT NULL, `targetAlert` REAL, `addedAt` INTEGER NOT NULL, PRIMARY KEY(`symbol`))
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT)
